---
import { getCollection } from "astro:content";
import CardWrapper from "../../components/CardWrapper.astro";
import Layout from "../../layouts/Layout.astro";
import { Card, CardTitle, CardDescription } from "../../components/ui/AnimatedCard";

const posts = (await getCollection("writing", ({ data }) => import.meta.env.PROD ? !data.draft : true))
  .sort((a, b) => b.data.date.valueOf() - a.data.date.valueOf());

const labels = [...new Set(posts.flatMap((p) => p.data.labels))].sort();
const minutes = (body = "") => Math.max(1, Math.round(body.split(/\s+/).length / 200));
---

<Layout title="Writing" description="Notes, essays and the occasional recipe of an idea.">
  <main class="flex flex-col justify-between items-center max-md:flex-col w-full max-w-200 mx-auto">
    <CardWrapper className="w-full py-6" enableWobble={false}>
      <Card className="bg-transparent w-full h-full p-6">
        <div class="flex justify-between items-center mb-4">
          <CardTitle className="text-2xl text-black-1">Writing</CardTitle>
          <a href="/rss.xml" class="text-sm text-blue-600 hover:underline">subscribe</a>
        </div>
        <CardDescription class:list={["text-sm", "leading-relaxed", "max-w-none"]}>
          <p class="mb-6">Things I'm chewing on, filed by label like recipes.</p>

          {labels.length > 0 && (
            <div class="flex flex-wrap gap-2 mb-6" id="labels">
              <button data-label="all" class="label-btn text-xs px-3 py-1 rounded-full border border-blue-1 text-blue-1">all</button>
              {labels.map((label) => (
                <button data-label={label} class="label-btn text-xs px-3 py-1 rounded-full border border-neutral-300 text-neutral-600 hover:border-blue-1 hover:text-blue-1">
                  {label}
                </button>
              ))}
            </div>
          )}

          <ul class="space-y-6 list-none p-0 m-0">
            {posts.map((post) => (
              <li class="post border-t border-neutral-200 pt-4" data-labels={post.data.labels.join(",")}>
                <a href={`/writing/${post.id}/`} class="group block no-underline">
                  <div class="flex justify-between items-baseline gap-4">
                    <h2 class="text-lg font-semibold text-black-1 group-hover:text-blue-1 m-0">{post.data.title}</h2>
                    <time class="text-xs text-neutral-500 shrink-0" datetime={post.data.date.toISOString()}>
                      {post.data.date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
                    </time>
                  </div>
                  <p class="text-neutral-600 mt-1 mb-2">{post.data.description}</p>
                </a>
                <div class="flex flex-wrap items-center gap-2 text-xs text-neutral-500">
                  {post.data.labels.map((label) => (
                    <span class="px-2 py-0.5 rounded-full bg-neutral-100 border border-neutral-200">{label}</span>
                  ))}
                  <span>· {minutes(post.body)} min read</span>
                  {post.data.draft && <span class="text-amber-600">· draft</span>}
                </div>
              </li>
            ))}
          </ul>

          {posts.length === 0 && <p class="text-neutral-500">Nothing published yet. Soon.</p>}
        </CardDescription>
      </Card>
    </CardWrapper>
  </main>
</Layout>

<script>
  // ponytail: client-side filter, no query params. Add deep links when someone wants to share one.
  document.getElementById("labels")?.addEventListener("click", (e) => {
    const btn = (e.target as HTMLElement).closest<HTMLElement>(".label-btn");
    if (!btn) return;
    const active = btn.dataset.label!;
    document.querySelectorAll<HTMLElement>(".label-btn").forEach((b) => {
      const on = b === btn;
      b.classList.toggle("border-blue-1", on);
      b.classList.toggle("text-blue-1", on);
      b.classList.toggle("border-neutral-300", !on);
      b.classList.toggle("text-neutral-600", !on);
    });
    document.querySelectorAll<HTMLElement>(".post").forEach((p) => {
      p.hidden = active !== "all" && !p.dataset.labels!.split(",").includes(active);
    });
  });
</script>
EOF
